{
 "openapi": "3.0.3",
 "info": {
  "title": "Freya Bank voice services: statement and debt (test environment mock)",
  "version": "1.0.0",
  "description": "Seven POST services under /voice/v1/. Request {data, call}; response {data, result}; success = HTTP 200 and result.returnCode '1'. Error answers carry result only. Dates dd.MM.yyyy strings, amounts JSON numbers. The test environment does not check tokens, headers, call or aiFlow."
 },
 "servers": [
  {
   "url": "https://yapmak-bank-mock.winter-mountain-4405.workers.dev"
  }
 ],
 "paths": {
  "/voice/v1/cards.list": {
   "post": {
    "summary": "Cards of the customer the assistant may talk about",
    "description": "Only active cards (status A) come back. Two cards can share productName and cardNumberLast4. productName is free text and may be empty.",
    "requestBody": {
     "required": true,
     "content": {
      "application/json": {
       "schema": {
        "type": "object",
        "description": "Contract envelope: service fields under data, call metadata under call",
        "properties": {
         "data": {
          "type": "object",
          "description": "Service request fields",
          "properties": {
           "customerNo": {
            "type": "string",
            "description": "Customer number the phone menu passes with the call; string or number both accepted"
           },
           "aiFlow": {
            "type": "string",
            "description": "Use case asking; 'CardOps' for this flow",
            "default": "CardOps"
           }
          },
          "required": [
           "customerNo",
           "aiFlow"
          ]
         },
         "call": {
          "type": "object",
          "description": "Call metadata the bank logs; not checked in the test environment",
          "properties": {
           "ani": {
            "type": "string",
            "description": "Caller's phone number"
           },
           "lang": {
            "type": "string",
            "description": "Caller language code, e.g. tr"
           }
          }
         }
        },
        "required": [
         "data"
        ]
       }
      }
     }
    },
    "responses": {
     "200": {
      "description": "success (result.returnCode '1')",
      "content": {
       "application/json": {
        "schema": {
         "type": "object",
         "properties": {
          "data": {
           "type": "object",
           "description": "Card list",
           "properties": {
            "cards": {
             "type": "array",
             "description": "The customer's eligible credit cards",
             "items": {
              "type": "object",
              "properties": {
               "cardNumber": {
                "type": "string",
                "description": "Masked card number (first six and last four visible); send this value unchanged to the card-level services"
               },
               "cardNumberLast4": {
                "type": "string",
                "description": "Last four digits (not unique)"
               },
               "productName": {
                "type": "string",
                "description": "Card product name as the card system returns it; may be an empty string"
               },
               "status": {
                "type": "string",
                "description": "Card status; 'A' active"
               },
               "isMainCard": {
                "type": "boolean",
                "description": "false for a card that is not the customer's own main card (supplementary); it is still listed"
               }
              }
             }
            },
            "validCardsCount": {
             "type": "integer",
             "description": "Number of cards returned"
            },
            "exitState": {
             "type": "string",
             "description": "'1_CARD' or 'MULTI_CARD'"
            }
           }
          },
          "result": {
           "type": "object",
           "description": "Result envelope, present on every answer. Success = HTTP 200 and returnCode '1'.",
           "properties": {
            "guid": {
             "type": "string",
             "description": "Trace id"
            },
            "returnCode": {
             "type": "string",
             "description": "'1' on success; otherwise an error code (INVALID_ARGUMENTS_ERROR, FB_IVR_CHANNEL_1xx, FBE00099)"
            },
            "messageText": {
             "type": "string",
             "description": "Log message, not for the caller"
            },
            "code": {
             "type": "string",
             "description": "Same as returnCode"
            },
            "message": {
             "type": "string",
             "description": "Same as messageText"
            },
            "type": {
             "type": "string",
             "description": "null on success, 'ERROR' or 'WARNING' on failure"
            },
            "details": {
             "type": "object",
             "properties": {
              "guid": {
               "type": "string",
               "description": "Trace id"
              },
              "rootCause": {
               "type": "string",
               "description": "Diagnostic"
              },
              "errorOrigin": {
               "type": "string",
               "description": "Diagnostic"
              }
             }
            }
           }
          }
         }
        }
       }
      }
     },
     "404": {
      "description": "FB_IVR_CHANNEL_102 (result.type WARNING): the customer has no valid card the assistant can work with. Not a service failure.",
      "content": {
       "application/json": {
        "schema": {
         "type": "object",
         "description": "Error answer: no data object, only result",
         "properties": {
          "result": {
           "type": "object",
           "description": "Result envelope, present on every answer. Success = HTTP 200 and returnCode '1'.",
           "properties": {
            "guid": {
             "type": "string",
             "description": "Trace id"
            },
            "returnCode": {
             "type": "string",
             "description": "'1' on success; otherwise an error code (INVALID_ARGUMENTS_ERROR, FB_IVR_CHANNEL_1xx, FBE00099)"
            },
            "messageText": {
             "type": "string",
             "description": "Log message, not for the caller"
            },
            "code": {
             "type": "string",
             "description": "Same as returnCode"
            },
            "message": {
             "type": "string",
             "description": "Same as messageText"
            },
            "type": {
             "type": "string",
             "description": "null on success, 'ERROR' or 'WARNING' on failure"
            },
            "details": {
             "type": "object",
             "properties": {
              "guid": {
               "type": "string",
               "description": "Trace id"
              },
              "rootCause": {
               "type": "string",
               "description": "Diagnostic"
              },
              "errorOrigin": {
               "type": "string",
               "description": "Diagnostic"
              }
             }
            }
           }
          }
         }
        }
       }
      }
     },
     "500": {
      "description": "FBE00099: technical error on the bank's side (result.type ERROR)",
      "content": {
       "application/json": {
        "schema": {
         "type": "object",
         "description": "Error answer: no data object, only result",
         "properties": {
          "result": {
           "type": "object",
           "description": "Result envelope, present on every answer. Success = HTTP 200 and returnCode '1'.",
           "properties": {
            "guid": {
             "type": "string",
             "description": "Trace id"
            },
            "returnCode": {
             "type": "string",
             "description": "'1' on success; otherwise an error code (INVALID_ARGUMENTS_ERROR, FB_IVR_CHANNEL_1xx, FBE00099)"
            },
            "messageText": {
             "type": "string",
             "description": "Log message, not for the caller"
            },
            "code": {
             "type": "string",
             "description": "Same as returnCode"
            },
            "message": {
             "type": "string",
             "description": "Same as messageText"
            },
            "type": {
             "type": "string",
             "description": "null on success, 'ERROR' or 'WARNING' on failure"
            },
            "details": {
             "type": "object",
             "properties": {
              "guid": {
               "type": "string",
               "description": "Trace id"
              },
              "rootCause": {
               "type": "string",
               "description": "Diagnostic"
              },
              "errorOrigin": {
               "type": "string",
               "description": "Diagnostic"
              }
             }
            }
           }
          }
         }
        }
       }
      }
     }
    },
    "operationId": "cards_list"
   }
  },
  "/voice/v1/cards.balance": {
   "post": {
    "summary": "Statement and due dates and the debt per currency of one card",
    "description": "Debt blocks debtTL, debtUSD, debtEUR, debtGBP; any block can be missing.",
    "requestBody": {
     "required": true,
     "content": {
      "application/json": {
       "schema": {
        "type": "object",
        "description": "Contract envelope: service fields under data, call metadata under call",
        "properties": {
         "data": {
          "type": "object",
          "description": "Service request fields",
          "properties": {
           "cardNumber": {
            "type": "string",
            "description": "cardNumber exactly as cards.list returned it (masked in the test environment, e.g. 540000******1234); never rebuilt from digits the caller says"
           }
          },
          "required": [
           "cardNumber"
          ]
         },
         "call": {
          "type": "object",
          "description": "Call metadata the bank logs; not checked in the test environment",
          "properties": {
           "ani": {
            "type": "string",
            "description": "Caller's phone number"
           },
           "lang": {
            "type": "string",
            "description": "Caller language code, e.g. tr"
           }
          }
         }
        },
        "required": [
         "data"
        ]
       }
      }
     }
    },
    "responses": {
     "200": {
      "description": "success (result.returnCode '1')",
      "content": {
       "application/json": {
        "schema": {
         "type": "object",
         "properties": {
          "data": {
           "type": "object",
           "description": "Balance",
           "properties": {
            "cardNumber": {
             "type": "string",
             "description": "Masked differently from cards.list (first 4 + last 4); do not use it for matching"
            },
            "cardNumberLast4": {
             "type": "string",
             "description": "Last four digits"
            },
            "productName": {
             "type": "string",
             "description": "Card product name"
            },
            "statementDate": {
             "type": "string",
             "description": "Date of the last issued statement, format dd.MM.yyyy (e.g. 05.11.2026)"
            },
            "lastPayDate": {
             "type": "string",
             "description": "Due date of the last issued statement, format dd.MM.yyyy (e.g. 05.11.2026)"
            },
            "nextStatementDate": {
             "type": "string",
             "description": "Coming statement date, format dd.MM.yyyy (e.g. 05.11.2026)"
            },
            "nextLastPayDate": {
             "type": "string",
             "description": "Coming due date, format dd.MM.yyyy (e.g. 05.11.2026)"
            },
            "debtTL": {
             "type": "object",
             "description": "Debt block for Türk Lirası (TL). The block can be MISSING for a card without this currency; a missing block is not NO_DEBT.",
             "properties": {
              "statementPaymentStatus": {
               "type": "string",
               "description": "HAS_DEBT or NO_DEBT for the statement debt in this currency"
              },
              "transferAmount": {
               "type": "number",
               "description": "Amount carried over from the previous period"
              },
              "statementDebt": {
               "type": "number",
               "description": "Statement debt"
              },
              "minPayment": {
               "type": "number",
               "description": "Minimum payment on the statement"
              },
              "remainingDebt": {
               "type": "number",
               "description": "What is left of the statement debt after payments since the statement; 0 when fully paid"
              },
              "remainingMinPayment": {
               "type": "number",
               "description": "What is left of the minimum payment after payments since the statement; 0 when the minimum was paid"
              },
              "currentPeriodExpense": {
               "type": "number",
               "description": "Spending after the statement"
              },
              "totalDebt": {
               "type": "number",
               "description": "Total debt including spending after the statement; negative = credit balance"
              },
              "totalDebtPaymentStatus": {
               "type": "string",
               "description": "HAS_DEBT or NO_DEBT for the total debt"
              },
              "remainAutomaticPaymentAmount": {
               "type": "number",
               "description": "Remaining automatic payment amount; only meaningful when automaticPaymentFlag is Y"
              }
             }
            },
            "debtUSD": {
             "type": "object",
             "description": "Debt block for Dolar (USD). The block can be MISSING for a card without this currency; a missing block is not NO_DEBT.",
             "properties": {
              "statementPaymentStatus": {
               "type": "string",
               "description": "HAS_DEBT or NO_DEBT for the statement debt in this currency"
              },
              "transferAmount": {
               "type": "number",
               "description": "Amount carried over from the previous period"
              },
              "statementDebt": {
               "type": "number",
               "description": "Statement debt"
              },
              "minPayment": {
               "type": "number",
               "description": "Minimum payment on the statement"
              },
              "remainingDebt": {
               "type": "number",
               "description": "What is left of the statement debt after payments since the statement; 0 when fully paid"
              },
              "remainingMinPayment": {
               "type": "number",
               "description": "What is left of the minimum payment after payments since the statement; 0 when the minimum was paid"
              },
              "currentPeriodExpense": {
               "type": "number",
               "description": "Spending after the statement"
              },
              "totalDebt": {
               "type": "number",
               "description": "Total debt including spending after the statement; negative = credit balance"
              },
              "totalDebtPaymentStatus": {
               "type": "string",
               "description": "HAS_DEBT or NO_DEBT for the total debt"
              },
              "remainAutomaticPaymentAmount": {
               "type": "number",
               "description": "Remaining automatic payment amount; only meaningful when automaticPaymentFlag is Y"
              }
             }
            },
            "debtEUR": {
             "type": "object",
             "description": "Debt block for Euro (EUR). The block can be MISSING for a card without this currency; a missing block is not NO_DEBT.",
             "properties": {
              "statementPaymentStatus": {
               "type": "string",
               "description": "HAS_DEBT or NO_DEBT for the statement debt in this currency"
              },
              "transferAmount": {
               "type": "number",
               "description": "Amount carried over from the previous period"
              },
              "statementDebt": {
               "type": "number",
               "description": "Statement debt"
              },
              "minPayment": {
               "type": "number",
               "description": "Minimum payment on the statement"
              },
              "remainingDebt": {
               "type": "number",
               "description": "What is left of the statement debt after payments since the statement; 0 when fully paid"
              },
              "remainingMinPayment": {
               "type": "number",
               "description": "What is left of the minimum payment after payments since the statement; 0 when the minimum was paid"
              },
              "currentPeriodExpense": {
               "type": "number",
               "description": "Spending after the statement"
              },
              "totalDebt": {
               "type": "number",
               "description": "Total debt including spending after the statement; negative = credit balance"
              },
              "totalDebtPaymentStatus": {
               "type": "string",
               "description": "HAS_DEBT or NO_DEBT for the total debt"
              },
              "remainAutomaticPaymentAmount": {
               "type": "number",
               "description": "Remaining automatic payment amount; only meaningful when automaticPaymentFlag is Y"
              }
             }
            },
            "debtGBP": {
             "type": "object",
             "description": "Debt block for İngiliz Sterlini (GBP). The block can be MISSING for a card without this currency; a missing block is not NO_DEBT.",
             "properties": {
              "statementPaymentStatus": {
               "type": "string",
               "description": "HAS_DEBT or NO_DEBT for the statement debt in this currency"
              },
              "transferAmount": {
               "type": "number",
               "description": "Amount carried over from the previous period"
              },
              "statementDebt": {
               "type": "number",
               "description": "Statement debt"
