                "code": { "type": "string", "default": "import json\ndef s(k):\n    v = vars.get(k)\n    return '' if v is None else str(v).strip()\ndef dg(x):\n    return ' '.join(list(str(x)))\ndef digits(x):\n    return ''.join(ch for ch in str(x or '') if ch.isdigit())\ndef obj(v):\n    if isinstance(v, (list, dict)):\n        return v\n    if isinstance(v, str) and v.strip()[:1] in ('[', '{'):\n        try:\n            return json.loads(v)\n        except Exception:\n            try:\n                import ast\n                return ast.literal_eval(v)\n            except Exception:\n                return None\n    return None\ndef flat_list(prefix):\n    items = dict()\n    for k in list(vars.keys()):\n        k = str(k)\n        if not k.startswith(prefix):\n            continue\n        rest = k[len(prefix):].replace('[', '.').replace(']', '')\n        bits = [x for x in rest.split('.') if x]\n        if len(bits) == 2 and bits[0].isdigit():\n            items.setdefault(int(bits[0]), dict())[bits[1]] = vars.get(k)\n    return [items[i] for i in sorted(items)]\ndef nm(c):\n    return c['name'] or ('sonu ' + dg(c['last4']) + ' ile biten kart')\ndef join_tr(ns):\n    if len(ns) <= 1:\n        return ''.join(ns)\n    return ', '.join(ns[:-1]) + ' ve ' + ns[-1]\nfor k, v in [('sel_tries', 0), ('card_name_said', ''), ('card_digits_said', ''), ('select_intent', 'none'), ('week_state', 'open'), ('email_sent_count', 0), ('offer_choice', 'none'), ('other_card_answer', 'none'), ('email_answer', 'none'), ('confirm_answer', 'none'), ('wanted_week', 'none'), ('week_answer', 'none'), ('oos_answer', 'none'), ('offer_lead', ''), ('reading_text', ''), ('reading_kind', ''), ('pdf_rc', '')]:\n    vars[k] = v\ntry:\n    raw = obj(vars.get('cards_raw'))\n    if not isinstance(raw, list):\n        raw = flat_list('load_cards_response.data.data.cards')\n    cards = []\n    for c in raw:\n        if not isinstance(c, dict):\n            continue\n        n = str(c.get('cardNumber') or '')\n        l4 = str(c.get('cardNumberLast4') or '') or digits(n)[-4:]\n        cards.append(dict(number=n, last4=l4, name=str(c.get('productName') or '').strip(), main=str(c.get('isMainCard')).lower() != 'false'))\n    vars['cards_json'] = json.dumps(cards, ensure_ascii=False)\n    elig = [c for c in cards if c['main']] or cards\n    vars['card_count'] = len(elig)\n    names = []\n    for c in elig:\n        if nm(c) not in names:\n            names.append(nm(c))\n    vars['card_names_text'] = join_tr(names)\n    ex = [x for x in names if not x.startswith('sonu ') and len(x.split()) <= 4 and len(x) <= 30][:2]\n    q = 'Hangi kartınızın borcunu öğrenmek istersiniz?'\n    if len(ex) == 2:\n        q = q + ' Örneğin, ' + ex[0] + ' veya ' + ex[1] + ' diyebilirsiniz.'\n    elif len(ex) == 1:\n        q = q + ' Örneğin, ' + ex[0] + ' diyebilirsiniz.'\n    vars['select_question'] = q\n    vars['select_prompt'] = q\n    if len(elig) == 1:\n        c = elig[0]\n        vars['selected_card_number'] = c['number']\n        vars['selected_card_last4'] = c['last4']\n        vars['selected_card_name'] = c['name']\n        vars['card_state'] = 'resolved'\n    elif len(elig) == 0:\n        vars['card_state'] = 'none'\n    else:\n        vars['card_state'] = 'choose'\nexcept Exception:\n    vars['card_state'] = 'error'\ntry:\n    em = s('contact_email') or s('load_contact_response.data.data.ibanEmail')\n    ok = '@' in em\n    if s('contact_rc') == '1' or s('load_contact_response.data.result.returnCode') == '1':\n        vars['email_state'] = 'ok' if ok else 'none'\n    else:\n        vars['email_state'] = 'error'\n    vars['registered_email'] = em if ok else ''\n    q2 = ''\n    if ok:\n        local, dom = em.split('@', 1)\n        messy = len(local) > 20 or any(ch.isdigit() for ch in local) or sum(local.count(x) for x in '.-_') > 1\n        if messy:\n            dn = dom.split('.')[0]\n            q2 = 'Ekstrenizi ' + local[:1] + ' ile başlayan ' + dn[:1].upper() + dn[1:] + ' adresinize göndermemi ister misiniz?'\n        else:\n            q2 = 'Ekstrenizi ' + em + ' adresine göndermemi ister misiniz?'\n    vars['email_question'] = q2\nexcept Exception:\n    vars['email_state'] = 'error'\n    vars['email_question'] = ''\n" },
