                "code": { "type": "string", "default": "import json\ndef s(k):\n    v = vars.get(k)\n    return '' if v is None else str(v).strip()\ndef dg(x):\n    return ' '.join(list(str(x)))\ndef digits(x):\n    return ''.join(ch for ch in str(x or '') if ch.isdigit())\ndef norm(t):\n    t = str(t or '').replace('I', 'ı').replace('İ', 'i').lower()\n    t = ''.join(ch if (ch.isalnum() or ch.isspace()) else ' ' for ch in t)\n    return ' '.join(t.split())\ndef nm(c):\n    return c.get('name') or ('sonu ' + dg(c.get('last4')) + ' ile biten kart')\ndef join_tr(ns):\n    if len(ns) <= 1:\n        return ''.join(ns)\n    return ', '.join(ns[:-1]) + ' ve ' + ns[-1]\ndef uniq(lst):\n    out = []\n    for c in lst:\n        if nm(c) not in out:\n            out.append(nm(c))\n    return out\nSTOP = ['kart', 'kartı', 'kartım', 'kartımın', 'kartımı', 'kartını', 'kartlarım', 'olan', 'benim', 'borcu', 'borcunu', 'lütfen', 'ile', 'biten', 'sonu', 'none', 'null']\ntry:\n    cards = json.loads(s('cards_json') or '[]')\n    elig = [c for c in cards if c.get('main')] or cards\n    said = norm(vars.get('card_name_said'))\n    dd = digits(vars.get('card_digits_said'))\n    intent = s('select_intent')\n    q = s('select_question')\n    toks = [t for t in said.split() if t not in STOP]\n    cand = list(cards)\n    if toks:\n        def tok_ok(c):\n            ct = norm(c.get('name')).split()\n            return all(any(x.startswith(t) or (len(t) >= 4 and t.startswith(x)) for x in ct) for t in toks)\n        cand = [c for c in cand if tok_ok(c)]\n        full = [c for c in cand if norm(c.get('name')) and norm(c.get('name')) in said]\n        if full:\n            m = max(len(norm(c.get('name'))) for c in full)\n            cand = [c for c in full if len(norm(c.get('name'))) == m]\n    if dd:\n        keep = []\n        for c in cand:\n            n = str(c.get('number') or '').replace(' ', '')\n            if len(dd) == 4:\n                if c.get('last4') == dd:\n                   