'Söylediğiniz bilgiyle eşleşen bir kartınız bulunmuyor. Kartlarınız: ' + join_tr(uniq(elig)) + '. Hangisinin borcunu öğrenmek istersiniz?'\n        else:\n            p = q\n        if t >= 3:\n            state = 'tries'\n    vars['select_prompt'] = p\n    vars['card_state'] = state\nexcept Exception:\n    vars['select_prompt'] = s('select_question')\n    vars['card_state'] = 'retry'\nvars['card_name_said'] = ''\nvars['card_digits_said'] = ''\nvars['select_intent'] = 'none'\n" },
