                "code": { "type": "string", "default": "import json, datetime\nMONTHS = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']\ndef s(k):\n    v = vars.get(k)\n    return '' if v is None else str(v).strip()\ndef num(v):\n    try:\n        return float(v)\n    except Exception:\n        return None\ndef pd(t):\n    try:\n        t = str(t or '').strip()\n        if len(t) >= 10 and t[2] == '.' and t[5] == '.':\n            return datetime.date(int(t[6:10]), int(t[3:5]), int(t[0:2]))\n        if len(t) >= 10 and t[4] == '-' and t[7] == '-':\n            return datetime.date(int(t[0:4]), int(t[5:7]), int(t[8:10]))\n    except Exception:\n        pass\n    return None\ndef fd(t):\n    d = pd(t)\n    return '' if d is None else str(d.day) + ' ' + MONTHS[d.month - 1] + ' ' + str(d.year)\ndef cop(n):\n    U = ['', 'dir', 'dir', 'tür', 'tür', 'tir', 'dır', 'dir', 'dir', 'dur']\n    T = ['', 'dur', 'dir', 'dur', 'tır', 'dir', 'tır', 'tir', 'dir', 'dır']\n    if n % 10:\n        return U[n % 10]\n    if n % 100:\n        return T[(n % 100) // 10]\n    if n % 1000:\n        return 'dür'\n    return 'dir'\ndef fdc(t):\n    d = pd(t)\n    return '' if d is None else fd(t) + chr(39) + cop(d.year)\ndef dg(x):\n    return ' '.join(list(str(x)))\ndef obj(v):\n    if isinstance(v, (list, dict)):\n        return v\n    if isinstance(v, str) and v.strip()[:1] in ('[', '{'):\n        try:\n            return json.loads(v)\n        except Exception:\n            try:\n                import ast\n                return ast.literal_eval(v)\n            except Exception:\n                return None\n    return None\nCUR = dict(TL=('Türk Lirası', 'lira', 'kuruş'), USD=('Dolar', 'Dolar', 'sent'), EUR=('Euro', 'Euro', 'sent'), GBP=('İngiliz Sterlini', 'İngiliz Sterlini', 'peni'))\nSUF = dict(TL='dır', USD='dır', EUR='dur', GBP='dir')\nSUB = dict(kuruş='tur', sent='tir', peni='dir')\ndef amt(cur, x, end=False):\n    c = i